  let mut total=LIMIT;let mut output=Vec::new();assert_eq!(preparation_diagnostic(b"x",&mut total,&mut output).unwrap_err().kind(),io::ErrorKind::OutOfMemory);assert!(output.is_empty());assert_eq!(total,LIMIT);
